style.css:
@-moz-document domain("web.vk.me") {
/* ---------- Палитра Telegram Web A (theme-dark) ---------- */
:root,
.vkui--vkBase--dark,
.MEConfig {
  --tg-primary: #8774e1;
  --tg-primary-shade: #7b71c6;
  --tg-primary-tint: rgba(135, 116, 225, .1);
  --tg-bg: #212121;
  --tg-own: #766ac8;
  --tg-own-selected: #6549d4;
  --tg-chat-hover: #2c2c2c;
  --tg-chat-active: #766ac8;
  --tg-text: #ffffff;
  --tg-text-secondary: #aaaaaa;
  --tg-borders: #303030;
  --tg-meta-own: rgba(255, 255, 255, .53);
  --tg-green: #00c73e;
  --tg-gray: #717579;
  --tg-shadow: rgba(16, 16, 16, .61);
  --tg-shadow-island: 0 1px 4px 0 rgba(0, 0, 0, .05);
  --tg-shadow-pane: 0 1px 5px -1px rgba(0, 0, 0, .21);
  --tg-shadow-footer: 0 1px 8px 1px rgba(0, 0, 0, .12);
  --tg-radius-island: 2.0rem;
  --tg-radius-msg-input: 2.0rem;
  --tg-radius-msg: .9375rem;
  --tg-radius-msg-small: .375rem;
  --tg-container: 47.5rem;
  --tg-font: "Roboto", -apple-system, BlinkMacSystemFont, "Apple Color Emoji", "Segoe UI", Oxygen, Ubuntu, Cantarell, "Fira Sans", "Droid Sans", "Helvetica Neue", sans-serif;
  --tg-padding-msg-input: 0.25rem;
  
  /* Фон-обои: чёрный + фиолетовый градиент + узор Telegram */
  --tg-wallpaper-bg: #000;
  --tg-wallpaper-gradient: radial-gradient(ellipse at 20% 0%, rgba(68, 48, 140, .35), transparent 60%),
                           radial-gradient(ellipse at 90% 100%, rgba(52, 40, 120, .3), transparent 60%);
  --tg-pattern: url("https://web.telegram.org/a/assets/pattern-YlWUl53U.svg");
  --tg-pattern-opacity: .09;

  /* Переопределение токенов VKUI */
  --vkui--color_background_content: var(--tg-bg) !important;
  --vkui--color_background: var(--tg-bg) !important;
  --vkui--color_background_secondary: var(--tg-chat-hover) !important;
  --vkui--color_background_secondary_alpha: var(--tg-chat-hover) !important;
  --vkui--color_background_modal: var(--tg-bg) !important;
  --vkui--color_background_accent: var(--tg-primary) !important;
  --vkui--color_background_accent_themed: var(--tg-primary) !important;
  --vkui--color_background_accent_themed--hover: var(--tg-primary-shade) !important;
  --vkui--color_background_accent_themed--active: var(--tg-primary-shade) !important;
  --vkui--color_text_primary: var(--tg-text) !important;
  --vkui--color_text_secondary: var(--tg-text-secondary) !important;
  --vkui--color_text_subhead: var(--tg-text-secondary) !important;
  --vkui--color_text_tertiary: var(--tg-text-secondary) !important;
  --vkui--color_text_accent: var(--tg-primary) !important;
  --vkui--color_text_accent_themed: var(--tg-primary) !important;
  --vkui--color_text_link: var(--tg-primary) !important;
  --vkui--color_icon_accent: var(--tg-primary) !important;
  --vkui--color_icon_accent_themed: var(--tg-primary) !important;
  --vkui--color_icon_secondary: var(--tg-text-secondary) !important;
  --vkui--color_icon_tertiary: var(--tg-text-secondary) !important;
  --vkui--color_icon_medium: var(--tg-text-secondary) !important;
  --vkui--color_stroke_accent: var(--tg-primary) !important;
  --vkui--color_stroke_accent_themed: var(--tg-primary) !important;
  --vkui--color_separator_primary: var(--tg-borders) !important;
  --vkui--color_separator_primary_alpha: var(--tg-borders) !important;
  --vkui--color_field_background: var(--tg-chat-hover) !important;
  --vkui--color_search_field_background: var(--tg-chat-hover) !important;
  --vkui--color_transparent--hover: var(--tg-chat-hover) !important;
  --vkui--color_transparent--active: var(--tg-chat-hover) !important;
  --vkui--color_overlay_primary: rgba(0, 0, 0, .4) !important;
  --vkui--font_family_base: var(--tg-font) !important;
  --vkui--font_family_accent: var(--tg-font) !important;

  /* Токены мессенджера */
  --font: var(--tg-font) !important;
  --convoHistoryBackgroundColor: transparent !important;
  --convoListItemHeight: 72px !important;
  --convoListItemVerticalPadding: 9px !important;
  --convoListItemHeaderFontSize: 16px !important;
  --convoListItemHeaderLineHeight: 22px !important;
  --convoListItemMessageFontSize: 16px !important;
  --convoListItemMessageLineHeight: 22px !important;
  --convoListItemDateFontSize: 12px !important;
  --messageFontSize: 16px !important;
  --messageLineHeight: 21px !important;
  --convoMainMaxWidth: var(--tg-container) !important;
  --vkui--vkontakte_color_im_bubble_incoming_alternate: var(--tg-bg) !important;
  --vkui--vkontakte_color_im_bubble_incoming: var(--tg-bg) !important;
  --vkui--vkontakte_color_im_bubble_outgoing: var(--tg-own) !important;
  --vkui--vkontakte_color_im_bubble_outgoing--active: var(--tg-own-selected) !important;
  --messageOutBubbleBackground: var(--tg-own) !important;
  --messageBorderRadius: var(--tg-radius-msg) !important;
  --composerBackgroundColor: transparent !important;
  --im_bubble_incoming_alternate_highlighted: #2c2c2c !important;
  --im_bubble_outgoing_highlighted: var(--tg-own-selected) !important;
  --im_reaction_chip_incoming: #2b2a35 !important;
  --im_reaction_chip_outgoing: #675caf !important;
  --im_reaction_chip_incoming--active: var(--tg-primary) !important;
  --im_reaction_chip_outgoing--active: #fff !important;
  --im_reaction_chip_incoming_text: var(--tg-text) !important;
  --im_reaction_chip_outgoing_text: var(--tg-text) !important;
  --im_reaction_chip_outgoing_text--active: var(--tg-own) !important;
}

body, .MEApp, .MEConfig {
  font-family: var(--tg-font) !important;
  -webkit-font-smoothing: antialiased;
}

::selection { background: var(--tg-primary-tint); }

.sbarThumb { background: rgba(255, 255, 255, .2) !important; border-radius: 4px !important; }

/* ---------- Общий фон-обои на всё окно ---------- */
.MEApp {
  background: var(--tg-wallpaper-gradient), var(--tg-wallpaper-bg) !important;
  isolation: isolate;
}
.MEApp::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image: var(--tg-pattern);
  background-size: 26.875rem auto;
  background-repeat: repeat;
  background-position: center;
  filter: invert(1);
  opacity: var(--tg-pattern-opacity);
}
.MEApp__content,
.RightPanelContainer,
.RightPanelContainer__mainContent,
.ConvoMain,
.ConvoMain__themeWrapper,
.ConvoMain__popupWrapper,
.ConvoMain__history,
.ConvoHistory {
  background: transparent !important;
}

/* ---------- Левая колонка — «островок» ---------- */
.CollapsibleContainer__content {
  box-sizing: border-box !important;
  padding: .5rem .5rem .5rem .5rem !important;
}
.MEAppMainPanel {
  height: 100% !important;
  border-radius: var(--tg-radius-island) !important;
  background-color: var(--tg-bg) !important;
  box-shadow: var(--tg-shadow-island) !important;
  border: none !important;
  overflow: hidden !important;
}
.ConvoList,
.ConvoList__header,
.ConvoList__headerContent,
.ConvoList__top,
.ConvoList__items,
.ConvoList__item,
.ConvoList__footer {
  background-color: var(--tg-bg) !important;
}
.ConvoList__headerContent { border-radius: 0 !important; }
.CollapsibleContainer__widthControllerArea { background: transparent !important; }

.vkmListHeader__title, .ConvoListLogo__title { color: var(--tg-text) !important; font-weight: 500 !important; }
.vkmListHeader__button,
.BurgerMenu__button {
  color: var(--tg-text-secondary) !important;
  border-radius: 50% !important;
  width: 2.5rem !important;
  height: 2.5rem !important;
}
.vkmListHeader__button:hover,
.BurgerMenu__button:hover { background-color: var(--tg-chat-hover) !important; }
.CollapsibleContainer::after { width: 0 !important; }
/* Поиск — «пилюля» */
.ConvoList__search .vkuiSearch__field {
  background-color: var(--tg-chat-hover) !important;
  border: 2px solid var(--tg-chat-hover) !important;
  border-radius: 1.375rem !important;
  min-height: 2.5rem !important;
  box-shadow: none !important;
  transition: border-color .15s !important;
}
.ConvoList__search .vkuiSearch__field:focus-within {
  border-color: var(--tg-primary) !important;
  background-color: var(--tg-bg) !important;
}
.ConvoList__search .vkuiSearch__field:focus-within .vkuiSearch__label { color: var(--tg-primary) !important; }
.vkuiSearch__nativeInput { color: var(--tg-text) !important; font-size: 1rem !important; }
.vkuiSearch__nativeInput::placeholder { color: var(--tg-text-secondary) !important; }

/* Фильтры */
.ConvoListFilter {
  background: transparent !important;
  color: var(--tg-text-secondary) !important;
  border-radius: .75rem !important;
  font-weight: 500 !important;
}
.ConvoListFilter:hover { background: var(--tg-chat-hover) !important; }

/* Элементы списка */
.ConvoList__scrollbar-content { padding: 0 .5rem !important; }
.ConvoListItem {
  border-radius: .75rem !important;
  padding-left: .5625rem !important;
  padding-right: .5625rem !important;
  color: var(--tg-text) !important;
}
.ConvoListItem::before { border-radius: .75rem !important; }
.ConvoListItem:hover::before { opacity: 1 !important; background: var(--tg-chat-hover) !important; }
.ConvoListItem.ConvoListItem--selected::before,
.ConvoListItem.ConvoListItem--selected:hover::before {
  opacity: 1 !important;
  background: var(--tg-chat-active) !important;
}

/* Аватар 54px как в TG (масштабируем, чтобы не ломать маски VK) */
.ConvoListItem__avatar {
  width: 54px !important;
  height: 54px !important;
  margin-right: .5rem !important;
}
.ConvoListItem__avatar > .MEAvatar {
  transform: scale(1.125);
  transform-origin: 0 0;
}

.ConvoTitle__title, .ConvoTitle__author {
  color: var(--tg-text) !important;
  font-weight: 500 !important;
  font-size: 1rem !important;
}
.ConvoListItem__text,
.ConvoListItem__date,
.ConvoListItem .MessagePreview {
  color: var(--tg-text-secondary) !important;
  font-weight: 400 !important;
}
.ConvoListItem__author { color: var(--tg-text) !important; font-weight: 400 !important; }
.ConvoListItem__date { font-size: .75rem !important; }
.ConvoListItem__draftLabel { color: #e53935 !important; }

.ConvoListItem--selected .ConvoTitle__title,
.ConvoListItem--selected .ConvoListItem__text,
.ConvoListItem--selected .ConvoListItem__author,
.ConvoListItem--selected .ConvoListItem__date,
.ConvoListItem--selected .MessagePreview,
.ConvoListItem--selected .ConvoTitle__icon,
.ConvoListItem--selected .ConvoListItem__pinIcon,
.ConvoListItem--selected .ConvoListItem__outStatusIcon { color: #fff !important; }

/* Счётчик непрочитанных */
.UnreadCounter {
  background: var(--tg-green) !important;
  color: #fff !important;
  font-weight: 500 !important;
  border-radius: .75rem !important;
  min-width: 1.5rem !important;
  height: 1.5rem !important;
  line-height: 1.5rem !important;
  font-size: .875rem !important;
  padding: 0 .4375rem !important;
}
.UnreadCounter--muted { background: var(--tg-gray) !important; }
.ConvoListItem--selected .UnreadCounter { background: #fff !important; color: var(--tg-own) !important; }

.MEAvatar__online { background-color: #0ac630 !important; border-color: var(--tg-bg) !important; }
.ConvoListItem--selected .MEAvatar__online { border-color: var(--tg-chat-active) !important; }

.ConvoList__item--separator { border-bottom: none !important; }
.ConvoList__footer { border-top: 1px solid var(--tg-borders) !important; color: var(--tg-text-secondary) !important; }

/* ---------- Шапка чата — «островок» ---------- */
.ConvoHeader {
  box-sizing: border-box !important;
  width: calc(100% - 1rem) !important;
  max-width: calc(var(--tg-container) - 1rem) !important;
  height: 3.5rem !important;
  margin: .5rem auto 0 !important;
  padding: .25rem .5rem .25rem 1rem !important;
  background-color: var(--tg-bg) !important;
  border: none !important;
  border-radius: var(--tg-radius-island) !important;
  box-shadow: var(--tg-shadow-pane) !important;
  z-index: 2;
}
.ConvoHeader .ConvoTitle__author, .ConvoHeader .ConvoTitle__title {
  font-size: 1rem !important;
  font-weight: 500 !important;
  line-height: 1.375rem !important;
  color: var(--tg-text) !important;
}
.ConvoHeader__status { color: var(--tg-text-secondary) !important; font-size: .875rem !important; font-weight: 400 !important; }
.ConvoHeader__avatar { width: 2.5rem !important; height: 2.5rem !important; margin-right: .625rem !important; }
.ConvoHeader__avatar > .MEAvatar { transform: scale(1.25); transform-origin: 0 0; }
.ConvoHeader__action {
  color: var(--tg-text-secondary) !important;
  border-radius: 50% !important;
  width: 2.5rem !important;
  height: 2.5rem !important;
}
.ConvoHeader__action:hover { background-color: var(--tg-chat-hover) !important; }

/* ---------- Сообщения ---------- */
.ConvoMessage__background {
  border-radius: var(--tg-radius-msg) !important;
  box-shadow: 0 1px 2px var(--tg-shadow) !important;
}
.ConvoMessage--in .ConvoMessage__background { background: var(--tg-bg) !important; }
.ConvoMessage--out .ConvoMessage__background { background: var(--tg-own) !important; }

/* Группировка: малые углы внутри серии */
.ConvoStack:not(.ConvoStack--out) .ConvoStack__content > .VirtualScrollItem:not(:last-child) .ConvoMessage__background {
  border-bottom-left-radius: var(--tg-radius-msg-small) !important;
}
.ConvoStack:not(.ConvoStack--out) .ConvoStack__content > .VirtualScrollItem:not(:first-child) .ConvoMessage__background {
  border-top-left-radius: var(--tg-radius-msg-small) !important;
}
.ConvoStack--out .ConvoStack__content > .VirtualScrollItem:not(:last-child) .ConvoMessage__background {
  border-bottom-right-radius: var(--tg-radius-msg-small) !important;
}
.ConvoStack--out .ConvoStack__content > .VirtualScrollItem:not(:first-child) .ConvoMessage__background {
  border-top-right-radius: var(--tg-radius-msg-small) !important;
}

/* Текст обычного начертания */
.ConvoStack,
.MessageText,
.ConvoMessage__text {
  font-size: 1rem !important;
  line-height: 1.3125 !important;
  font-weight: 400 !important;
  color: var(--tg-text) !important;
}
.ConvoMessage--out .MessageText, .ConvoMessage--out .ConvoMessage__text { color: #fff !important; }
.ConvoMessage a { color: var(--tg-primary) !important; }
.ConvoMessage--out .MessageText a { color: #fff !important; text-decoration: underline; }

/* Время */
.ConvoMessage__date, .ConvoMessageBottomInfo__date {
  font-size: .75rem !important;
  font-weight: 400 !important;
  color: rgba(170, 170, 170, .75) !important;
}
.ConvoMessage--out .ConvoMessage__date,
.ConvoMessage--out .ConvoMessageBottomInfo__date,
.ConvoMessage--out .ConvoMessageBottomInfo { color: var(--tg-meta-own) !important; }

/* Имя автора */
.ConvoMessageHeader .PeerTitle__title,
.ConvoMessage__authorName .PeerTitle__title {
  color: var(--tg-primary) !important;
  font-weight: 500 !important;
  font-size: .875rem !important;
}

/* Ответ */
.Reply {
  background: var(--tg-primary-tint) !important;
  border-radius: .25rem !important;
  border-left: 3px solid var(--tg-primary) !important;
  padding: .1875rem .375rem !important;
}
.Reply::before { display: none !important; }
.Reply__author { color: var(--tg-primary) !important; font-weight: 500 !important; font-size: .875rem !important; }
.Reply__content, .Reply .MessagePreview { color: var(--tg-text) !important; font-weight: 400 !important; font-size: .875rem !important; }
.ConvoMessage--out .Reply { background: rgba(255, 255, 255, .12) !important; border-left-color: #fff !important; }
.ConvoMessage--out .Reply__author,
.ConvoMessage--out .Reply__content,
.ConvoMessage--out .Reply .MessagePreview { color: #fff !important; }

/* Даты и сервисные сообщения */
.DateSeparator {
  background-color: rgba(34, 41, 46, .85) !important;
  color: #fff !important;
  font-weight: 500 !important;
  font-size: .9375rem !important;
  line-height: 1.75rem !important;
  padding: 0 .5rem !important;
  border-radius: 1.75rem !important;
}
.ServiceMessage, .ServiceMessage__preview { color: #fff !important; }
.ServiceMessage--withBubble .ServiceMessage__preview {
  background-color: rgba(34, 41, 46, .85) !important;
  border-radius: .75rem !important;
  font-weight: 500 !important;
  padding: .125rem .5rem !important;
}
.ServiceMessage__link, .ServiceMessage__highlight { color: #fff !important; font-weight: 500 !important; }

.ConvoHopNavigation button,
.ConvoMain__historyUnread button {
  background: var(--tg-bg) !important;
  color: var(--tg-text-secondary) !important;
  border-radius: 50% !important;
  box-shadow: 0 1px 2px var(--tg-shadow) !important;
}

/* ---------- Поле ввода: однострочный островок + круглая кнопка ---------- */
.ConvoMain__composerWrapper,
.ConvoMain__composer { background: transparent !important; border-top: none !important; box-shadow: none !important; }
.ConvoMain__composer { padding: 0 .5rem .5rem !important; }
.ConvoMain__composerContent.ConvoComposer {
  background: var(--tg-bg) !important;
  box-shadow: none !important;
  border-radius: var(--tg-radius-msg-input) !important;
  padding: var(--tg-padding-msg-input) !important;
}
.ConvoComposer__inputPanel {
  align-items: center !important;
  margin-right: 4rem;
  position: relative;
}
.ConvoComposer__inputWrapper { align-self: center !important; margin: 0 .25rem !important; }
.ConvoComposer__input.ConvoComposer__input.ConvoComposer__input {
  margin: 1.0625rem 0 !important;
  padding: 0 !important;
  color: var(--tg-text) !important;
  font-weight: 400 !important;
}
.ConvoComposer__inputPlaceholder {  color: var(--tg-text-secondary) !important; font-weight: 400 !important; }
.ComposerInput__placeholder { color: var(--tg-text-secondary) !important; }

.ConvoComposer__button {
  color: var(--tg-text-secondary) !important;
  background: transparent !important;
  border-radius: 50% !important;
  opacity: 1 !important;
  width: 2.75rem !important;
  min-width: 2.75rem !important;
  height: 2.75rem !important;
  margin: .375rem 0 !important;
}
.ConvoComposer__button:hover { color: var(--tg-primary) !important; }

/* Отправка / микрофон — залитый фиолетовый круг справа */
.ConvoComposer__inputPanel button[data-testid="vkme_composer_send"] {
  position: absolute !important;
  right: -4rem !important;
  bottom: 0 !important;
  width: 3.5rem !important;
  min-width: 3.5rem !important;
  height: 3.5rem !important;
  margin: 0 !important;
  border-radius: 50% !important;
  background: var(--tg-primary) !important;
  color: #fff !important;
  box-shadow: var(--tg-shadow-footer) !important;
  transition: background-color .15s !important;
}
.ConvoComposer__inputPanel button[data-testid="vkme_composer_send"]:hover {
  background: var(--tg-primary-shade) !important;
  color: #fff !important;
}

/* ---------- Меню, поповеры ---------- */
.vkuiActionSheet__host, .vkuiPopper__host,
.ComposerFormattingMenu__panel {
  background: rgba(33, 33, 33, .87) !important;
  backdrop-filter: blur(50px) !important;
  border-radius: .75rem !important;
  box-shadow: 0 .25rem .5rem .125rem var(--tg-shadow) !important;
}
.ComposerFormattingMenu__button { color: var(--tg-text) !important; }

/* ---------- Правая панель — тоже островок ---------- */
.RightPanel {
  background: transparent !important;
  border-left: none !important;
  padding: .5rem .5rem .5rem 0 !important;
  box-sizing: border-box !important;
}
.RightPanel__container {
  background: var(--tg-bg) !important;
  border-radius: var(--tg-radius-island) !important;
  overflow: hidden !important;
}
.ContentPlaceholder {
	background-color: #00000000 !important;
}
}
